": "P", "raia": "Inteligência · pessoa", "tipo_bpmn": "user", "condicao": "Há desvio relevante ou conclusão nova? Sim"}, {"jornada": "IN-04", "numero": 3, "ordem": 4, "nome": "Publicar os indicadores e a análise no painel único, com o acesso que cada ficha define", "executor": "R", "raia": "Inteligência · automação", "tipo_bpmn": "script", "condicao": null}]$j$::jsonb) as x(jornada text, numero smallint, ordem smallint, nome text, executor org.executor, raia text, tipo_bpmn text, condicao text) join org.etapa e on e.jornada = x.jornada and e.numero = x.numero;
